mapper.select:
select DISTINCT FIN_PRODUCT.FINPROD_MARKET_ID id, IFNULL(p.FINPROD_ABBR,FIN_PRODUCT.FINPROD_ABBR) text, IFNULL(p.FINPROD_ID,FIN_PRODUCT.FINPROD_ID) object, (CASE WHEN FIN_PRODUCT_ADD.DEAL_MODE =#{dealMode_10,jdbcType=VARCHAR} THEN #{yeOrNO_N,jdbcType=VARCHAR} ELSE fin_product_add.IS_LAY END) col
from FIN_CASH_PAY_RULE, FIN_CASH_INFO, FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON (PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID or PTL_MANAGE_OBJ.MANAGE_OBJ_ID= FIN_PRODUCT.P_FINPROD_ID) INNER JOIN FIN_PRODUCT_ADD D2 ON FIN_PRODUCT.FINPROD_ID = D2.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
LEFT JOIN FIN_PRODUCT P ON FIN_PRODUCT.P_FINPROD_ID = P.FINPROD_ID LEFT JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT_ADD.FINPROD_ID = P.FINPROD_ID and P.PROFIT_TYPE = #{PROFIT_TYPE_01} where FIN_PRODUCT.FINPROD_ID = FIN_CASH_PAY_RULE.FINPROD_ID AND FIN_CASH_PAY_RULE.PAY_CYCLE != #{payCycle,jdbcType=VARCHAR} AND FIN_PRODUCT.FINPROD_TYPE = #{finprodType2,jdbcType=VARCHAR} AND FIN_CASH_INFO.CASH_ID = FIN_CASH_PAY_RULE.CASH_ID AND FIN_CASH_INFO.CASH_TYPE_1 = #{cashType1}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',#{search},'%') OR FIN_PRODUCT.FINPROD_ABBR like concat('%',#{search},'%') OR FIN_PRODUCT.P_FINPROD_ID like concat('%',#{search},'%' ) )
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue}
AND ((FIN_PRODUCT.PROFIT_TYPE != #{PROFIT_TYPE_02} and ((P.FINPROD_ID IS NOT NULL and D2.deal_mode != #{dealMode_01,jdbcType=VARCHAR}) or D2.deal_mode = #{dealMode_01,jdbcType=VARCHAR})) OR FIN_PRODUCT.PROFIT_TYPE = #{PROFIT_TYPE_02})

select FIN_PRODUCT.FINPROD_MARKET_ID id, FIN_PRODUCT.FINPROD_ABBR text, CONCAT_WS('', FIN_PRODUCT.FINPROD_ID , ',' , DATE_FORMAT(FIN_PRODUCT.VDATE,'%Y-%m-%d') , ',' , DATE_FORMAT(FIN_PRODUCT.MDATE,'%Y-%m-%d') , ',' , FIN_PRODUCT.PROFIT_TYPE , ',' , FIN_PRODUCT.CALENDAR_ID , ',' , DATE_FORMAT(FIN_PRODUCT.LIQUIDATION_DATE,'%Y-%m-%d') ) object, case when FIN_PRODUCT.PROFIT_TYPE = #{profitType_02} then #{YES_OR_NO_N} when FIN_PRODUCT_ADD.DEAL_MODE = #{dealMode_10} then #{YES_OR_NO_N} else FIN_PRODUCT_ADD.IS_LAY end as col
from FIN_PRODUCT INNER JOIN PTL_MANAGE_OBJ ON PTL_MANAGE_OBJ.MANAGE_OBJ_ID = FIN_PRODUCT.FINPROD_ID INNER JOIN PTL_PORTFOLIO_AUTHORITY ON PTL_MANAGE_OBJ.PORTFOLIO_ID = PTL_PORTFOLIO_AUTHORITY.PORTFOLIO_ID
AND PTL_PORTFOLIO_AUTHORITY.USER_ID = #{userId}
INNER JOIN FIN_PRODUCT_ADD ON FIN_PRODUCT.FINPROD_ID = FIN_PRODUCT_ADD.FINPROD_ID AND FIN_PRODUCT_ADD.ISSUE_STATUS = #{ISSUE_STATUS_01}
FIN_PRODUCT.FINPROD_TYPE2 = #{args0,jdbcType=VARCHAR}
AND (FIN_PRODUCT.FINPROD_MARKET_ID like concat('%',#{search,jdbcType=VARCHAR},'%') OR FIN_PRODUCT.FINPROD_ABBR like concat('%',#{search,jdbcType=VARCHAR},'%'))
AND FIN_PRODUCT.FINPROD_MARKET_ID = #{initValue}

SELECT distinct PRD_LAYER_PARAM.PROD_STYLE text, FIN_PRODUCT.FINPROD_ID id, CONCAT_WS('', FIN_PRODUCT.FINPROD_ID , ',' , DATE_FORMAT(FIN_PRODUCT.VDATE,'%Y-%m-%d') , ',' , DATE_FORMAT(FIN_PRODUCT.MDATE,'%Y-%m-%d') , ',' , FIN_PRODUCT.PROFIT_TYPE , ',' , FIN_PRODUCT.CALENDAR_ID , ',' , DATE_FORMAT(FIN_PRODUCT.LIQUIDATION_DATE,'%Y-%m-%d') ) object FROM PRD_LAYER_PARAM,FIN_CASH_INFO,FIN_PRODUCT WHERE PRD_LAYER_PARAM.FINPROD_ID = FIN_CASH_INFO.FINPROD_ID AND FIN_CASH_INFO.CASH_TYPE_1 =#{cashType1_03} AND PRD_LAYER_PARAM.FINPROD_ID = FIN_PRODUCT.FINPROD_ID
AND PRD_LAYER_PARAM.P_FINPROD_ID = #{pfinprodId}
AND (FIN_PRODUCT.FINPROD_ABBR like concat('%',#{search,jdbcType=VARCHAR},'%') OR PRD_LAYER_PARAM.PROD_STYLE like concat('%',#{search,jdbcType=VARCHAR},'%'))
AND PRD_LAYER_PARAM.FINPROD_ID = #{initValue}
